## `InfluxService.java`

```java
import com.influxdb.v3.client.InfluxDBClient;
import com.influxdb.v3.client.Point;
import com.influxdb.v3.client.query.QueryOptions;
import com.influxdb.v3.client.query.QueryType;
import io.github.cdimascio.dotenv.Dotenv;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;

public final class InfluxService implements AutoCloseable {

    private static final Pattern DB_NAME = Pattern.compile("\"iox::database\"\\s*:\\s*\"([^\"]*)\"");

    private final InfluxDBClient client;
    private final String database;

    public InfluxService() throws Exception {
        Dotenv env = Dotenv.configure().ignoreIfMissing().load();
        String host = require(env, "INFLUXDB_HOST").replaceAll("/+$", "");
        String token = require(env, "INFLUXDB_TOKEN");
        this.database = require(env, "INFLUXDB_DATABASE");

        // InfluxDB 3 silently auto-creates a database on first write, so a typo
        // in INFLUXDB_DATABASE would "succeed" into the wrong database. Fail fast instead.
        verifyDatabaseExists(host, token, database);

        this.client = InfluxDBClient.getInstance(host, token.toCharArray(), database);
    }

    private static void verifyDatabaseExists(String host, String token, String db) throws Exception {
        HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();
        HttpRequest req = HttpRequest.newBuilder(URI.create(host + "/api/v3/configure/database?format=json"))
            .header("Authorization", "Bearer " + token)
            .timeout(Duration.ofSeconds(10))
            .GET().build();
        HttpResponse<String> resp = http.send(req, HttpResponse.BodyHandlers.ofString());

        if (resp.statusCode() == 401 || resp.statusCode() == 403) {
            throw new IllegalStateException("InfluxDB rejected INFLUXDB_TOKEN (HTTP " + resp.statusCode()
                + "). Check the token is valid and scoped to db:" + db + ":read,write.");
        }
        if (resp.statusCode() != 200) {
            throw new IllegalStateException("Could not list databases at " + host + " (HTTP " + resp.statusCode() + ")");
        }
        Set<String> names = new HashSet<>();
        Matcher m = DB_NAME.matcher(resp.body());
        while (m.find()) names.add(m.group(1));
        if (!names.contains(db)) {
            throw new IllegalStateException("Database '" + db + "' does not exist (visible: " + names
                + "). Create it with: influxdb3 create database " + db + " --token <admin-token>");
        }
    }

    public void write(List<Point> points) {
        client.writePoints(points); // batch ~1,000 points or flush every ~1s
    }

    public List<Object[]> recentByHost(String host) {
        QueryOptions opts = new QueryOptions().withQueryType(QueryType.SQL)
            .withParameters(Map.of("host", host)); // never concatenate user input into SQL
        try (Stream<Object[]> rows = client.query(
                "SELECT * FROM sensor WHERE host = $host AND time > now() - INTERVAL '1 hour' "
                    + "ORDER BY time DESC LIMIT 100", opts)) {
            return rows.toList();
        }
    }

    @Override
    public void close() throws Exception {
        client.close();
    }

    private static String require(Dotenv env, String key) {
        String v = env.get(key); // dotenv-java falls back to real env vars
        if (v == null || v.isBlank()) throw new IllegalStateException("Missing required env var " + key);
        return v;
    }
}
