package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"math/rand"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/InfluxCommunity/influxdb3-go/v2/influxdb3"
	"github.com/influxdata/line-protocol/v2/lineprotocol"
	"github.com/joho/godotenv"
)

func main() {
	_ = godotenv.Load()

	host := strings.TrimRight(mustEnv("INFLUXDB_HOST"), "/")
	token := mustEnv("INFLUXDB_TOKEN")
	database := mustEnv("INFLUXDB_DATABASE")

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	// Stop here if the database is missing, so a typo doesn't create a new one.
	if err := ensureDatabaseExists(ctx, host, token, database); err != nil {
		log.Fatal(err)
	}

	client, err := influxdb3.New(influxdb3.ClientConfig{
		Host:     host,
		Token:    token,
		Database: database,
	})
	if err != nil {
		log.Fatalf("client init: %v", err)
	}
	defer client.Close()

	// Sample data: 3 sensors, one reading per minute for the last 10 minutes.
	sensors := []struct{ id, location string }{
		{"sensor-001", "warehouse-a"},
		{"sensor-002", "warehouse-a"},
		{"sensor-003", "warehouse-b"},
	}
	now := time.Now().Truncate(time.Second)

	points := make([]*influxdb3.Point, 0, len(sensors)*10)
	for _, s := range sensors {
		for i := 10; i > 0; i-- {
			points = append(points,
				influxdb3.NewPointWithMeasurement("sensor_readings").
					SetTag("sensor_id", s.id).
					SetTag("location", s.location).
					SetField("temperature", 20.0+rand.Float64()*5).
					SetField("humidity", 40.0+rand.Float64()*15).
					SetField("battery", 100-int64(rand.Intn(20))).
					SetTimestamp(now.Add(-time.Duration(i)*time.Minute)),
			)
		}
	}

	fmt.Printf("Writing %d points to %q on %s\n", len(points), database, host)
	if err := client.WritePoints(ctx, points, influxdb3.WithPrecision(lineprotocol.Second)); err != nil {
		log.Fatalf("write failed: %v", err)
	}

	// Read the data back to confirm the write.
	iter, err := client.Query(ctx,
		"SELECT sensor_id, location, temperature, humidity, battery, time "+
			"FROM sensor_readings ORDER BY time DESC LIMIT 5")
	if err != nil {
		log.Fatalf("query failed: %v", err)
	}
	fmt.Println("Most recent rows:")
	for iter.Next() {
		fmt.Println(" ", iter.Value())
	}
	if err := iter.Err(); err != nil {
		log.Fatalf("iterate: %v", err)
	}
}

// ensureDatabaseExists lists databases via /api/v3/configure/database and errors if the target is missing.
func ensureDatabaseExists(ctx context.Context, host, token, database string) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet,
		host+"/api/v3/configure/database?format=json", nil)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+token)

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return fmt.Errorf("cannot reach InfluxDB at %s: %w", host, err)
	}
	defer resp.Body.Close()

	switch resp.StatusCode {
	case http.StatusOK:
	case http.StatusUnauthorized, http.StatusForbidden:
		return fmt.Errorf("listing databases returned %d: check INFLUXDB_TOKEN", resp.StatusCode)
	default:
		return fmt.Errorf("listing databases returned unexpected status %d", resp.StatusCode)
	}

	var rows []map[string]string
	if err := json.NewDecoder(resp.Body).Decode(&rows); err != nil {
		return fmt.Errorf("decode database list: %w", err)
	}
	names := make([]string, 0, len(rows))
	for _, r := range rows {
		if r["iox::database"] == database {
			return nil
		}
		names = append(names, r["iox::database"])
	}
	return fmt.Errorf("database %q not found (existing: %v). Create it with:\n  influxdb3 create database %s --token <admin-token>",
		database, names, database)
}

func mustEnv(k string) string {
	v := os.Getenv(k)
	if v == "" {
		log.Fatalf("missing env var %s (set it in .env or your shell)", k)
	}
	return v
}
