	}
	defer client.Close()

	ctx := context.Background()
	now := time.Now().Truncate(time.Second)

	sensors := []struct{ id, room string }{
		{"sensor-001", "kitchen"},
		{"sensor-002", "living_room"},
		{"sensor-003", "garage"},
	}

	// 10 readings per sensor, one per minute, ending now
	points := make([]*influxdb3.Point, 0, len(sensors)*10)
	for s, sensor := range sensors {
		for i := 0; i < 10; i++ {
			ts := now.Add(time.Duration(i-9) * time.Minute)
			points = append(points,
				influxdb3.NewPointWithMeasurement("home_sensors").
					SetTag("sensor_id", sensor.id).
					SetTag("room", sensor.room).
					SetField("temperature", 20.0+float64(s)*1.5+float64(i)*0.2).
					SetField("humidity", 40.0+float64(s)*2.0+float64(i)*0.5).
					SetField("co2_ppm", int64(400+s*25+i*3)).
					SetTimestamp(ts),
			)
		}
	}

	fmt.Printf("==> Writing %d points to %q on %s\n", len(points), database, host)
	if err := client.WritePoints(ctx, points, influxdb3.WithPrecision(lineprotocol.Second)); err != nil {
		log.Fatalf("write: %v", err)
	}

	fmt.Println("==> Reading back the latest rows")
	iter, err := client.Query(ctx,
		"SELECT time, sensor_id, room, temperature, humidity, co2_ppm "+
			"FROM home_sensors ORDER BY time DESC LIMIT 5")
	if err != nil {
		log.Fatalf("query: %v", err)
	}
	for iter.Next() {
		fmt.Println(iter.Value())
	}
	if err := iter.Err(); err != nil {
		log.Fatalf("iterate: %v", err)
	}
	fmt.Println("==> Done")
}

// requireDatabase stops the program if the target database doesn't exist,
// so the write can't auto-create a misspelled one.
func requireDatabase(host, token, database string) error {
	req, err := http.NewRequest(http.MethodGet, host+"/api/v3/configure/database?format=json", nil)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+token)

	resp, err := (&http.Client{Timeout: 10 * time.Second}).Do(req)
	if err != nil {
		return fmt.Errorf("cannot reach InfluxDB at %s: %w", host, err)
	}
	defer resp.Body.Close()

	switch {
	case resp.StatusCode == http.StatusUnauthorized || resp.StatusCode == http.StatusForbidden:
		return fmt.Errorf("listing databases failed (%d): check INFLUXDB_TOKEN", resp.StatusCode)
	case resp.StatusCode != http.StatusOK:
		return fmt.Errorf("listing databases failed: HTTP %d", resp.StatusCode)
	}

	var rows []map[string]string
	if err := json.NewDecoder(resp.Body).Decode(&rows); err != nil {
		return fmt.Errorf("decode database list: %w", err)
	}
	names := make([]string, 0, len(rows))
	for _, r := range rows {
		name := r["iox::database"]
		if name == database {
			return nil
		}
		names = append(names, name)
	}
	return fmt.Errorf("database %q not found (existing: %s). Create it with:\n"+
		"  influxdb3 create database %s --token <admin-token>",
		database, strings.Join(names, ", "), database)
}

func mustEnv(k string) string {
	v := os.Getenv(k)
	if v == "" {
		log.Fatalf("missing env var %s (see .env.example)", k)
	}
	return v
}
