```javascript
import 'dotenv/config';
import { InfluxDBClient } from '@influxdata/influxdb3-client';

export function loadConfig() {
  const host = process.env.INFLUXDB_HOST;
  const token = process.env.INFLUXDB_TOKEN;
  const database = process.env.INFLUXDB_DATABASE;

  const missing = Object.entries({ INFLUXDB_HOST: host, INFLUXDB_TOKEN: token, INFLUXDB_DATABASE: database })
    .filter(([, value]) => !value)
    .map(([name]) => name);
  if (missing.length > 0) {
    throw new Error(`Missing required env vars: ${missing.join(', ')} (see .env.example)`);
  }

  return { host: host.replace(/\/+$/, ''), token, database };
}

// Cloud Serverless has no /api/v3 endpoints, so check the bucket through the v2 buckets API.
export async function assertBucketExists({ host, token, database }) {
  const url = `${host}/api/v2/buckets?name=${encodeURIComponent(database)}`;
  const res = await fetch(url, { headers: { Authorization: `Token ${token}` } });

  if (res.status === 401 || res.status === 403) {
    throw new Error(
      `Token rejected (${res.status}) when listing buckets on ${host}. ` +
        'Check INFLUXDB_TOKEN, INFLUXDB_HOST (region URL), and that the token can read the bucket.'
    );
  }
  if (!res.ok) {
    throw new Error(`Bucket lookup failed: HTTP ${res.status} ${await res.text()}`);
  }

  const { buckets = [] } = await res.json();
  if (!buckets.some((b) => b.name === database)) {
    throw new Error(
      `Bucket "${database}" not found on ${host}. Create it in the Cloud Serverless UI or with ` +
        '`influx bucket create`, or fix INFLUXDB_DATABASE.'
    );
  }
}

export async function connect() {
  const config = loadConfig();
  await assertBucketExists(config);
  // The client writes through /api/v2/write and queries over Flight, which is what Serverless supports.
  return new InfluxDBClient(config);
}
```

