});
if (!res.ok) throw new Error(`Listing databases failed: HTTP ${res.status}`);
const names = (await res.json()).map((d) => d['iox::database']);
if (!names.includes(database)) {
  throw new Error(`Database "${database}" not found. Available: ${names.join(', ')}`);
}

const client = new InfluxDBClient({ host, token, database });

// Range to export and window size. Adjust the window so each one holds roughly 100k–1M rows.
const START = new Date(process.env.EXPORT_START ?? '2026-01-01T00:00:00Z');
const END = new Date(process.env.EXPORT_END ?? '2026-09-29T00:00:00Z');
const WINDOW_MS = 60 * 60 * 1000; // 1 hour

const sql = `
  SELECT *
  FROM sensor
  WHERE time >= $start AND time < $end
  ORDER BY time
`;

let total = 0;
try {
  for (let t = START.getTime(); t < END.getTime(); t += WINDOW_MS) {
    const start = new Date(t).toISOString();
    const end = new Date(Math.min(t + WINDOW_MS, END.getTime())).toISOString();

    let count = 0;
    const rows = client.query(sql, database, { type: 'sql', params: { start, end } });
    for await (const row of rows) {
      await handleRow(row); // write to a file, another DB, etc.
      count++;
    }

    total += count;
    // Checkpoint: save `end` somewhere durable to resume from after a crash.
    console.log(`[${start} → ${end}) ${count} rows (total ${total})`);
  }
} finally {
  await client.close();
}

async function handleRow(row) {
  // your processing here
}
```

## Why this approach

- **Half-open windows (`>= start AND < end`)**: every row lands in exactly one window, with no duplicates or gaps at the boundaries.
- **No `LIMIT` inside a window**: with "`ORDER BY time LIMIT n`, then continue from the last timestamp," rows can be skipped or repeated. In InfluxDB 3, rows from different sensors (different tags) often share a timestamp, and a page can break in the middle of them. Fixed windows avoid that problem. If you must cap page size, order by `time` plus your tag columns (e.g. `ORDER BY time, sensor_id`) and continue from that pair.
- **Parameterized times**: the window bounds are passed as `params` rather than pasted into the SQL string.
- **Resumability**: save the last completed `end` after each window. On restart, set `EXPORT_START` to it.

## Tuning the window size

If your data is spread evenly, 10M rows over ~9 months is roughly 1,500 rows/hour. That's small enough to use a 1-day window. If data arrives in bursts, count first and size the windows from that:

```sql
SELECT DATE_BIN(INTERVAL '1 day', time) AS day, COUNT(*) AS n
FROM sensor
WHERE time >= $start AND time < $end
GROUP BY day ORDER BY day
```

If you only need a few columns, list them in the `SELECT` instead of `*`. That cuts transfer time a lot at this row count.

With 10 million rows, don't page with `LIMIT/OFFSET`. Each deeper page makes the server rescan and skip every row before it, so later pages keep getting slower. Split the data into **fixed time windows** instead (for example, one hour each) and stream each window. The official JS client returns rows as an async iterator over Arrow Flight, so each window streams in without being loaded into memory all at once.

Fixed windows are also safer than a "`time > last_seen_time LIMIT 1000`" cursor. With several sensors, many rows can share the same timestamp. That kind of cursor skips those rows silently at page boundaries. Fixed `[start, end)` windows never skip or repeat a row.

## Setup (Core)

1. **Check the server is running:** `curl -H "Authorization: Bearer $INFLUXDB_TOKEN" "$INFLUXDB_HOST/ping"` should return 200. A 401 also means the server is up and only your token is wrong.
2. **Token:** Core has admin tokens only. Give this app its own named token with `influxdb3 create token --admin --name sensor-export --token <operator-token>`. The secret is shown only once, so copy it right away.
3. **Database:** check that it exists with `influxdb3 show databases --token <token>`. The script also checks at startup and stops if the database is missing, so a typo in the name fails loudly instead of returning nothing.
4. **Install:** `npm install @influxdata/influxdb3-client dotenv`
5. **Env vars:** add `.env` to `.gitignore`, commit a `.env.example`, and set these values in `.env`:
   ```
   INFLUXDB_HOST=http://localhost:8181
   INFLUXDB_TOKEN=<your app token>
   INFLUXDB_DATABASE=sensor_data
   ```

## `page-sensors.js`

```javascript
import 'dotenv/config';
import { InfluxDBClient } from '@influxdata/influxdb3-client';

const host = process.env.INFLUXDB_HOST;
const token = process.env.INFLUXDB_TOKEN;
const database = process.env.INFLUXDB_DATABASE;
const table = process.env.TABLE ?? 'sensor';
const windowMs = Number(process.env.WINDOW_MINUTES ?? 60) * 60_000;

if (!host || !token || !database) {
  throw new Error('INFLUXDB_HOST, INFLUXDB_TOKEN, and INFLUXDB_DATABASE are required');
}

// Fail fast if the database doesn't exist (a typo would otherwise just return 0 rows).
async function assertDatabaseExists() {
  const res = await fetch(`${host}/api/v3/configure/database?format=json`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(`Listing databases failed: HTTP ${res.status}`);
  const dbs = (await res.json()).map((d) => d['iox::database']);
  if (!dbs.includes(database)) {
    throw new Error(`Database "${database}" not found. Existing: ${dbs.join(', ')}`);
  }
}

const client = new InfluxDBClient({ host, token, database });

// Figure out the overall time range once (or pass START/END to skip this).
async function timeRange() {
  if (process.env.START && process.env.END) {
    return [new Date(process.env.START), new Date(process.env.END)];
  }
  const rows = client.query(
    `SELECT CAST(MIN(time) AS VARCHAR) AS lo, CAST(MAX(time) AS VARCHAR) AS hi FROM "${table}"`,
    database,
    { type: 'sql' }
  );
  for await (const r of rows) {
    if (!r.lo) throw new Error(`Table "${table}" is empty`);
    return [new Date(r.lo + 'Z'), new Date(new Date(r.hi + 'Z').getTime() + 1)];
  }
}

async function* pageThrough(start, end) {
  for (let lo = start.getTime(); lo < end.getTime(); lo += windowMs) {
    const hi = Math.min(lo + windowMs, end.getTime());
    const rows = client.query(
      `SELECT * FROM "${table}"
       WHERE time >= to_timestamp($start) AND time < to_timestamp($end)
       ORDER BY time`,
      database,
      {
        type: 'sql',
        params: { start: new Date(lo).toISOString(), end: new Date(hi).toISOString() },
      }
    );
    yield { windowStart: new Date(lo), windowEnd: new Date(hi), rows };
  }
}

try {
  await assertDatabaseExists();
  const [start, end] = await timeRange();
  console.log(`==> Paging ${table} from ${start.toISOString()} to ${end.toISOString()}`);

  let total = 0;
  for await (const { windowStart, windowEnd, rows } of pageThrough(start, end)) {
    let n = 0;
    for await (const row of rows) {
      // process(row) — write to file, transform, forward, etc.
      n++;
    }
    total += n;
    // Log the checkpoint so you can resume with START=<windowEnd> after a crash.
    console.log(`${windowStart.toISOString()} → ${windowEnd.toISOString()}: ${n} rows (total ${total})`);
  }
  console.log(`==> Done: ${total} rows`);
} finally {
  await client.close();
}
```

Run it with `node page-sensors.js`. To export a specific range, run `START=2026-09-01T00:00:00Z END=2026-09-29T00:00:00Z node page-sensors.js`.

## Things to adjust

- **Window size:** aim for roughly 10k–500k rows per window. For example, 10M rows over 30 days is about 14k rows per hour, so the default 60 minutes is fine. Use smaller windows if a single query runs too long, and larger ones if you're making thousands of tiny queries.
- **Resuming:** each log line records the end of a completed window. If the run dies, restart with `START=<last windowEnd>`.
- **Narrow `SELECT *`** to the columns you need (and add `WHERE sensor_id = $id` if you only want some sensors). This cuts transfer time a lot.
- **Real UI-style pages** (like "next 1,000 rows" in a web app): add `LIMIT 1000` inside a window, and order by time plus every tag (`ORDER BY time, sensor_id`) so the order is fully deterministic. Short OFFSETs within one window are fine. The large OFFSETs across the whole table are what get slow.

