## `BulkWrite.cs`

```csharp
using System.Net;
using System.Net.Http.Headers;
using System.Text.Json;
using DotNetEnv;
using InfluxDB3.Client;
using InfluxDB3.Client.Write;

namespace InfluxBulk;

public static class BulkWrite {
    const int TotalPoints = 1_000_000;
    const int BatchSize = 10_000;      // start in the 1k–10k range
    const int MaxInFlight = 4;         // concurrent write requests
    const int MaxAttempts = 5;
    const int Devices = 1_000;         // 1,000 devices x 1,000 seconds = 1M unique points

    public static async Task Main() {
        Env.Load();
        var host = Require("INFLUXDB_HOST");
        var token = Require("INFLUXDB_TOKEN");
        var database = Require("INFLUXDB_DATABASE");

        await EnsureDatabaseExistsAsync(host, token, database);

        using var client = new InfluxDBClient(host: host, token: token, database: database);

        // Whole seconds, so second precision doesn't round anything away.
        var start = DateTimeOffset.FromUnixTimeSeconds(
            DateTimeOffset.UtcNow.ToUnixTimeSeconds() - TotalPoints / Devices);

        var written = 0;
        var sw = System.Diagnostics.Stopwatch.StartNew();

        await Parallel.ForEachAsync(
            Batches(start),
            new ParallelOptions { MaxDegreeOfParallelism = MaxInFlight },
            async (batch, ct) => {
                await WriteWithRetryAsync(client, batch, ct);
                var total = Interlocked.Add(ref written, batch.Count);
                if (total % 100_000 == 0) Console.WriteLine($"==> {total:N0} points");
            });

        Console.WriteLine($"==> Wrote {written:N0} points in {sw.Elapsed.TotalSeconds:F1}s " +
                          $"({written / sw.Elapsed.TotalSeconds:N0} pts/s)");
    }

    // Builds batches on demand, so all 1M points are never in memory at once.
    static IEnumerable<List<PointData>> Batches(DateTimeOffset start) {
        var rnd = new Random(42);
        var batch = new List<PointData>(BatchSize);
        for (var n = 0; n < TotalPoints; n++) {
            var device = n % Devices;
            var second = n / Devices;
            batch.Add(PointData.Measurement("sensor")
                .SetTag("device_id", $"dev-{device:D4}")
                .SetTag("region", device % 2 == 0 ? "us-west" : "us-east")
                .SetField("temperature", 20.0 + rnd.NextDouble() * 10)
                .SetField("humidity", 40.0 + rnd.NextDouble() * 20)
                .SetTimestamp(start.AddSeconds(second).UtcDateTime));

            if (batch.Count == BatchSize) {
                yield return batch;
                batch = new List<PointData>(BatchSize);
            }
        }
        if (batch.Count > 0) yield return batch;
    }

    static async Task WriteWithRetryAsync(InfluxDBClient client, List<PointData> batch, CancellationToken ct) {
        for (var attempt = 1; ; attempt++) {
            try {
                await client.WritePointsAsync(batch, precision: WritePrecision.S, cancellationToken: ct);
                return;
            } catch (Exception ex) when (attempt < MaxAttempts && IsRetriable(ex)) {
                // Exponential backoff with full jitter: up to 0.5s, 1s, 2s, 4s
                var delay = TimeSpan.FromMilliseconds(Random.Shared.Next(0, 500 * (1 << (attempt - 1))));
                Console.Error.WriteLine($"retriable error (attempt {attempt}): {ex.Message}; retrying in {delay.TotalMilliseconds:F0}ms");
                await Task.Delay(delay, ct);
            }
        }
    }

    // Retry 429, 5xx, and connection failures. 400/401/403/404/413 are bugs to fix, not retry.
    static bool IsRetriable(Exception ex) => ex switch {
        InfluxDBApiException api => api.StatusCode == HttpStatusCode.TooManyRequests || (int)api.StatusCode >= 500,
        HttpRequestException => true,
        TaskCanceledException => true, // HTTP timeout
        _ => false,
    };

    // Stop before writing if the database doesn't exist, instead of letting auto-create hide a typo.
    static async Task EnsureDatabaseExistsAsync(string host, string token, string database) {
        using var http = new HttpClient { BaseAddress = new Uri(host) };
        http.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", token);
        using var resp = await http.GetAsync("/api/v3/configure/database?format=json");

        if (resp.StatusCode is HttpStatusCode.Unauthorized or HttpStatusCode.Forbidden) {
            if (Environment.GetEnvironmentVariable("INFLUXDB_SKIP_DB_CHECK") == "1") return;
            throw new InvalidOperationException(
                $"Token can't list databases ({(int)resp.StatusCode}). Confirm '{database}' exists with " +
                "`influxdb3 show databases`, then set INFLUXDB_SKIP_DB_CHECK=1.");
        }
        resp.EnsureSuccessStatusCode();

        using var doc = JsonDocument.Parse(await resp.Content.ReadAsStringAsync());
        var names = doc.RootElement.EnumerateArray()
            .Select(e => e.GetProperty("iox::database").GetString())
            .ToHashSet();
        if (!names.Contains(database))
            throw new InvalidOperationException(
                $"Database '{database}' not found (have: {string.Join(", ", names)}). " +
                $"Create it: influxdb3 create database {database} --token <admin-token>");
    }

    static string Require(string k) =>
        Environment.GetEnvironmentVariable(k) ?? throw new InvalidOperationException($"missing env {k}");
}
```

## Why it's built this way

- **Batches, not single points.** 1M points becomes 100 requests of 10,000 points each. Writing one point per request would overload the server and run out of HTTP connections.
- **Low memory use.** `Batches()` yields one batch at a time, and `Parallel.ForEachAsync` keeps at most 4 requests in flight.
- **Second precision, with no silent overwrites.** Timestamps in whole seconds make each request smaller. Points with the same table, tags and timestamp overwrite each other, so the data is spread over 1,000 devices × 1,000 seconds. If you need more than one point per second per device, use `WritePrecision.Ms` or finer.
- **Retries only where they help.** 429, 5xx and dropped connections get exponential backoff with jitter, up to 5 attempts. A 400 (bad line protocol or a field type conflict), 401, 403, 404 or 413 fails straight away, because retrying won't fix it.
- **One bad line fails its whole batch.** Client 1.9.0+ writes through `/api/v2/write` by default. On Core or Enterprise you can set the `UseV2Api` write option to `false` to use `/api/v3/write_lp` instead. That endpoint keeps the valid lines and returns a 400 listing the rejected ones, so you resend only those.

## Things to check

- **Scoped tokens:** a scoped token may not be allowed to list databases. In that case the check stops with a clear message. Confirm the database once with the CLI, then set `INFLUXDB_SKIP_DB_CHECK=1`.
- **Your client version:** the exception type (`InfluxDBApiException` and its `StatusCode`) and the `precision:` argument are written from memory of recent `InfluxDB3.Client` releases. Check them against the version you install.
- **Tuning:** 10,000 points and 4 concurrent requests is a reasonable starting point, not a tuned value. Finding the best batch size for your workload is outside what I've covered here; see InfluxData's performance-tuning docs for that.

A 429 means the server is rate-limiting you. Nothing is wrong with the data itself, so the fix is to wait and resend the same batch, waiting a bit longer after each 429. (I'm assuming this is InfluxDB 3 with the `influxdb3-go` client. If it's a different service, tell me.)

## What to do

1. **Retry 429 and 5xx errors** with exponential backoff plus random jitter. Only 429 and 5xx are safe to retry this way.
2. **Don't retry 400, 401, 403 or 404.** Those won't go away on their own. A 400 means bad line protocol; 401 or 403 means a token problem.
3. **Cap the number of attempts** and return an error when you run out, so a long outage doesn't block your writer forever.
4. **Find out where the limit comes from.** InfluxDB Cloud Serverless rate-limits writes per organization. Self-hosted Core and Enterprise normally don't return 429, so if you run one of those, check whether a proxy or gateway in front of it is doing the limiting.

## Go retry wrapper

```go
package writer

import (
	"context"
	"errors"
	"fmt"
	"math/rand"
	"net/http"
	"strconv"
	"time"

	"github.com/InfluxCommunity/influxdb3-go/v2/influxdb3"
)

func retriable(status int) bool {
	return status == http.StatusTooManyRequests || status >= 500
}

// WriteWithRetry writes one batch, retrying 429/5xx with exponential backoff + jitter.
func WriteWithRetry(ctx context.Context, c *influxdb3.Client, points []*influxdb3.Point) error {
	const (
		maxAttempts = 6
		baseDelay   = 500 * time.Millisecond
		maxDelay    = 30 * time.Second
	)

	for attempt := 1; ; attempt++ {
		err := c.WritePoints(ctx, points)
		if err == nil {
			return nil
		}

		var se *influxdb3.ServerError
		if !errors.As(err, &se) || !retriable(se.StatusCode) {
			return err // 400/401/403/404 or a non-HTTP error: don't retry blindly
		}
		if attempt == maxAttempts {
			return fmt.Errorf("write failed after %d attempts: %w", attempt, err)
		}

		// Exponential backoff with full jitter.
		backoff := baseDelay << (attempt - 1)
		if backoff > maxDelay {
			backoff = maxDelay
		}
		delay := time.Duration(rand.Int63n(int64(backoff)) + 1)

		// Honor Retry-After when the server sends it.
		if se.Headers != nil {
			if s, perr := strconv.Atoi(se.Headers.Get("Retry-After")); perr == nil && s > 0 {
				delay = time.Duration(s) * time.Second
			}
		}

		select {
		case <-time.After(delay):
		case <-ctx.Done():
			return ctx.Err()
		}
	}
}
```

The `Headers` field on `ServerError` may not exist in older `influxdb3-go` versions. If the code doesn't compile against your version, delete the Retry-After block; backoff alone still works.

## Keeping 429s rare

- **Batch sensibly.** Send about 1,000 points per write or flush every second, whichever comes first. Many small requests hit rate limits sooner than fewer large ones.
- **Limit concurrent writers.** If several goroutines write at once, a 429 is a sign to reduce their number.
- **Watch for partial writes when retrying.** `influxdb3-go` 2.15.0 and later write through `/api/v2/write`, which accepts or rejects a whole batch, so resending the whole batch is correct. If you set `UseV2Api: false`, a 400 can mean some lines were already stored. In that case, resend only the rejected lines.

If 429s keep coming even with backoff, you're consistently over your plan's write limit. Spreading writes out over time or raising the limit with InfluxData are the real fixes. Tuning batch size for throughput is beyond this guide; see the InfluxDB performance docs for your product.

A 429 means the server is rate-limiting you. Retry the same batch after a delay that grows each time (exponential backoff with jitter). Don't treat it like a 400. The batch itself is fine; it was sent too fast.

## Retry loop in Go (`influxdb3-go` v2)

```go
import (
    "context"
    "errors"
    "math/rand"
    "net/http"
    "strconv"
    "time"

    "github.com/InfluxCommunity/influxdb3-go/v2/influxdb3"
)

func writeWithRetry(ctx context.Context, client *influxdb3.Client, points []*influxdb3.Point) error {
    const maxAttempts = 6
    backoff := 500 * time.Millisecond
    const maxBackoff = 30 * time.Second

    for attempt := 1; ; attempt++ {
        err := client.WritePoints(ctx, points)
        if err == nil {
            return nil
        }

        var se *influxdb3.ServerError
        retriable := false
        wait := backoff
        if errors.As(err, &se) {
            switch {
            case se.StatusCode == http.StatusTooManyRequests, se.StatusCode >= 500:
                retriable = true
                // Use the server's Retry-After if it sent one
                if se.Headers != nil {
                    if s, perr := strconv.Atoi(se.Headers.Get("Retry-After")); perr == nil && s > 0 {
                        wait = time.Duration(s) * time.Second
                    }
                }
            }
            // 400, 401, 403, 404, 413: not retriable. Fix the cause instead.
        } else {
            retriable = true // network error: connection reset or refused
        }

        if !retriable || attempt == maxAttempts {
            return err
        }

        // Full jitter keeps many writers from retrying at the same moment
        sleep := time.Duration(rand.Int63n(int64(wait)) + 1)
        select {
        case <-time.After(sleep):
        case <-ctx.Done():
            return ctx.Err()
        }
        backoff = min(backoff*2, maxBackoff)
    }
}
```

## Things to check

- **Set explicit timestamps before you retry.** If you leave them out, the server stamps each point with the time it arrives, so a retried batch gets new timestamps and you store duplicate data. With explicit timestamps, a retry is safe: points with the same table, tags and timestamp overwrite each other.
- **The whole batch was rejected.** Since v2.15.0, `influxdb3-go` writes through `/api/v2/write` by default, and a 429 there means none of the points were stored. Resend the full batch.
- **Which product are you on?** InfluxDB Cloud Serverless limits write rates per organization, which is the usual source of 429s. Self-hosted InfluxDB 3 Core or Enterprise normally doesn't return 429 unless something in front of it, like a proxy or gateway, is limiting you. If you're self-hosted, look there.
- **Frequent 429s mean you're sending too many requests.** Send fewer, larger batches: about 1,000 points or more per write, or flush once a second, whichever comes first. One write per point hits rate limits quickly.
- **Check the client version.** The `ServerError` field names (`StatusCode`, and especially `Headers`) depend on your `influxdb3-go` version. If `Headers` doesn't exist in yours, remove the Retry-After block and rely on backoff alone. I didn't compile this example.

If you tell me which InfluxDB 3 product you're on, I can point you to its specific rate limits.

A 429 means InfluxDB is rate-limiting you. The batch was rejected but it's safe to retry. Resend the same batch after a delay that grows with each attempt, with some randomness (jitter) added. If the server sends a `Retry-After` header, wait at least that long. Don't retry 400, 401, 403 or 404. Those won't succeed until you fix something.

```go
import (
    "context"
    "errors"
    "fmt"
    "math/rand"
    "net/http"
    "strconv"
    "time"

    "github.com/InfluxCommunity/influxdb3-go/v2/influxdb3"
)

func writeWithRetry(ctx context.Context, client *influxdb3.Client, points []*influxdb3.Point) error {
    const maxAttempts = 6
    backoff := 500 * time.Millisecond
    const maxBackoff = 30 * time.Second

    for attempt := 1; ; attempt++ {
        err := client.WritePoints(ctx, points)
        if err == nil {
            return nil
        }

        var se *influxdb3.ServerError
        if !errors.As(err, &se) || !retriable(se.StatusCode) || attempt == maxAttempts {
            return fmt.Errorf("write failed (attempt %d): %w", attempt, err)
        }

        // Full jitter: random delay in [0, backoff)
        delay := time.Duration(rand.Int63n(int64(backoff)))
        if ra := retryAfter(se); ra > delay {
            delay = ra
        }

        select {
        case <-time.After(delay):
        case <-ctx.Done():
            return ctx.Err()
        }
        backoff = min(backoff*2, maxBackoff)
    }
}

func retriable(code int) bool {
    return code == http.StatusTooManyRequests || code >= 500
}

func retryAfter(se *influxdb3.ServerError) time.Duration {
    if se.Headers == nil {
        return 0
    }
    if v := http.Header(se.Headers).Get("Retry-After"); v != "" {
        if secs, err := strconv.Atoi(v); err == nil {
            return time.Duration(secs) * time.Second
        }
    }
    return 0
}
```

This assumes your version of `influxdb3-go` has `ServerError.StatusCode` and `ServerError.Headers`. Older versions may not expose `Headers`. If yours doesn't, remove `retryAfter` and rely on the backoff alone.

**If you keep getting 429s:**
- **Which product are you on?** InfluxDB Cloud Serverless limits writes per organization, so 429s are expected when you exceed your plan. Self-hosted InfluxDB 3 Core and Enterprise usually don't return 429 unless something in front of them (a proxy or gateway) is limiting requests. Let me know which product it is if that's unclear.
- **Send fewer, larger requests.** Batch about 1,000 points or 1 second's worth of data per call, whichever comes first. Many small writes use up the limit faster than a few big ones.
- **Limit concurrent writers.** Several goroutines writing at once all hit the limit together. Route writes through one worker or a small fixed pool.
- **Stop after a set number of attempts.** Once retries run out, return the error, or save the batch to disk or a queue to send later. Otherwise a long throttle will stall your app.

If your Serverless plan's limit is simply too low for the volume you're sending, you'll need a higher plan tier.
